// مصنوعات دیپلوی نسخه ۳.۰ — تولیدشده خودکار از پوشه supabase/
// (بازتولید: bun run scripts/gen-v3-artifacts.ts)
// ============================================================
// تغییرات v3:
//   - دفترهای مستقل: تطابق دوطرفه حذف شد؛ هر کاربر آزادانه ثبت می‌کند
//   - شش نوع عملیات (kind) + دسته‌بندی شخصی + کامنت دوطرفه
//   - طرف‌حساب مشترک (با گرنت ادمین) / شخصی (فقط مالک)
//   - ادمین می‌تواند کاربران را غیرفعال کند (is_active)

export const SCHEMA_SQL_V3 = "-- ============================================================\n-- مهاجرت به نسخه ۳.۰ (۳.۰.۳) — دفترهای مستقل + دید دوجانبه + کامنت\n-- اجرا در: Supabase Dashboard → SQL Editor\n-- ✔ روی هر نصبی که نسخه ۲ (schema-v2.sql + telegram-schema.sql) را\n--   اجرا کرده، همین فایل را اجرا کنید. کاملاً idempotent است و\n--   اجرای چندباره خطا نمی‌دهد. داده‌های موجود حفظ می‌شوند\n--   (direction تراکنش‌های قدیمی به kind تبدیل می‌شود).\n-- ⚠ برای نصب از صفر: اول schema-v2.sql، بعد telegram-schema.sql، بعد این فایل.\n-- ✔ ترتیب: اول ستون‌ها و جدول‌ها، بعد توابع امنیتی (چون توابع\n--   language sql در لحظه ساخت اعتبارسنجی می‌شوند).\n-- ✔ خودترمیمی: جدول‌های ناقصِ به‌جامانده از تلاش‌های قبلی به‌طور\n--   خودکار شناسایی و از نو ساخته می‌شوند.\n-- ============================================================\n\n-- ============================================================\n-- ۰) خودترمیمی: جدول‌های ناقصِ به‌جامانده از تلاش‌های قبلی\n-- اگر جدولی از قبل با ساختار ناسازگار (مثلاً بدون ستون user_id)\n-- موجود باشد، حذف و در ادامه از نو ساخته می‌شود؛\n-- جدول‌های سالم و داده‌های درست دست‌نخورده می‌مانند.\n-- ============================================================\ndo $$\nbegin\n  -- categories باید user_id از نوع uuid داشته باشد\n  if exists (select 1 from information_schema.tables\n             where table_schema = 'public' and table_name = 'categories')\n     and not exists (\n       select 1 from information_schema.columns\n       where table_schema = 'public' and table_name = 'categories'\n         and column_name = 'user_id' and udt_name = 'uuid'\n     ) then\n    drop table public.categories cascade;\n  end if;\n\n  -- counterparty_access باید user_id از نوع uuid داشته باشد\n  if exists (select 1 from information_schema.tables\n             where table_schema = 'public' and table_name = 'counterparty_access')\n     and not exists (\n       select 1 from information_schema.columns\n       where table_schema = 'public' and table_name = 'counterparty_access'\n         and column_name = 'user_id' and udt_name = 'uuid'\n     ) then\n    drop table public.counterparty_access cascade;\n  end if;\n\n  -- transaction_comments باید author_id از نوع uuid داشته باشد\n  if exists (select 1 from information_schema.tables\n             where table_schema = 'public' and table_name = 'transaction_comments')\n     and not exists (\n       select 1 from information_schema.columns\n       where table_schema = 'public' and table_name = 'transaction_comments'\n         and column_name = 'author_id' and udt_name = 'uuid'\n     ) then\n    drop table public.transaction_comments cascade;\n  end if;\nend\n$$;\n\n-- حذف تریگرهای سرگردانِ به‌جامانده از تلاش‌های قبلی روی تراکنش‌ها\n-- (نسخه ۳ هیچ تریگری روی transactions ندارد؛ تریگر خراب می‌تواند\n--  خطای «column does not exist» هنگام UPDATE بدهد)\ndo $$\ndeclare r record;\nbegin\n  for r in\n    select trigger_name from information_schema.triggers\n    where event_object_schema = 'public' and event_object_table = 'transactions'\n      and trigger_name not like 'pg_%'\n  loop\n    execute format('drop trigger if exists %I on public.transactions', r.trigger_name);\n  end loop;\nend\n$$;\n\n-- ============================================================\n-- ۱) ساختار: ستون‌ها و جدول‌های جدید (قبل از توابع!)\n-- ============================================================\n\n-- ۱-۱) کاربران: ستون فعال/غیرفعال (ادمین می‌تواند کاربر را غیرفعال کند)\nalter table public.user_profiles\n  add column if not exists is_active boolean not null default true;\n\n-- ۱-۲) طرف‌حساب‌ها: مشترک/شخصی\nalter table public.counterparties\n  add column if not exists is_shared boolean not null default true,\n  add column if not exists owner_user_id uuid references auth.users(id) on delete cascade;\n\n-- (طرف‌حساب‌های موجود که ادمین ساخته → is_shared=true خودکار با DEFAULT)\n\n-- ۱-۳) جدول گرنت دسترسی به طرف‌حساب‌های مشترک\ncreate table if not exists public.counterparty_access (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references auth.users(id) on delete cascade,\n  counterparty_id uuid not null references public.counterparties(id) on delete cascade,\n  granted_by uuid references auth.users(id),\n  created_at timestamptz not null default now(),\n  unique (user_id, counterparty_id)\n);\n\n-- خودترمیمی ستون‌ها (اگر جدول از قبل با ستون‌های ناقص مانده)\nalter table public.counterparty_access\n  add column if not exists user_id uuid references auth.users(id) on delete cascade,\n  add column if not exists counterparty_id uuid references public.counterparties(id) on delete cascade,\n  add column if not exists granted_by uuid references auth.users(id),\n  add column if not exists created_at timestamptz not null default now();\n\n-- ۱-۴) دسته‌بندی‌های شخصی هر کاربر\ncreate table if not exists public.categories (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references auth.users(id) on delete cascade,\n  name text not null,\n  created_at timestamptz not null default now(),\n  unique (user_id, name)\n);\n\n-- خودترمیمی ستون‌ها\nalter table public.categories\n  add column if not exists user_id uuid references auth.users(id) on delete cascade,\n  add column if not exists name text,\n  add column if not exists created_at timestamptz not null default now();\n\n-- ۱-۵) کامنت روی ردیف تراکنش (دوطرفه)\ncreate table if not exists public.transaction_comments (\n  id uuid primary key default gen_random_uuid(),\n  transaction_id uuid not null references public.transactions(id) on delete cascade,\n  author_id uuid not null references auth.users(id) on delete cascade,\n  author_name text not null,\n  body text not null,\n  created_at timestamptz not null default now()\n);\n\n-- خودترمیمی ستون‌ها\nalter table public.transaction_comments\n  add column if not exists transaction_id uuid references public.transactions(id) on delete cascade,\n  add column if not exists author_id uuid references auth.users(id) on delete cascade,\n  add column if not exists author_name text,\n  add column if not exists body text,\n  add column if not exists created_at timestamptz not null default now();\n\n-- ۱-۶) تراکنش‌ها: ستون kind (شش نوع) + دسته‌بندی\nalter table public.transactions\n  add column if not exists kind text,\n  add column if not exists category_id uuid references public.categories(id) on delete set null;\n\n-- ============================================================\n-- ۲) توابع کمکی امن (SECURITY DEFINER — بدون درگیری RLS تودرتو)\n-- ============================================================\n\n-- آیا کاربر جاری ادمین است؟ (از schema-v2 موجود)\ncreate or replace function public.is_admin()\nreturns boolean\nlanguage sql security definer set search_path = public\nas $$\n  select exists (\n    select 1 from public.user_profiles\n    where id = auth.uid() and role = 'admin'\n  );\n$$;\n\n-- آیا کاربر جاری می‌تواند این طرف‌حساب را ببیند؟\n--   ادمین: همه | شخصی: فقط مالکش | مشترک: فقط با گرنت | لینک‌شده به خودش\ncreate or replace function public.cp_visible_to_me(v_cp uuid)\nreturns boolean\nlanguage sql security definer set search_path = public\nas $$\n  select exists (\n    select 1 from public.counterparties c\n    where c.id = v_cp\n      and (\n        exists (select 1 from public.user_profiles p where p.id = auth.uid() and p.role = 'admin' and p.is_active)\n        or (c.is_shared = false and c.owner_user_id = auth.uid())\n        or (\n          c.is_shared\n          and exists (\n            select 1 from public.counterparty_access a\n            where a.counterparty_id = v_cp and a.user_id = auth.uid()\n          )\n        )\n        or c.linked_user_id = auth.uid()\n      )\n  );\n$$;\n\n-- آیا کاربر جاری می‌تواند این تراکنش را ببیند؟\n--   صاحب دفتر یا کسی که تراکنش روی طرف‌حسابِ لینک‌شده به اوست\ncreate or replace function public.txn_visible_to_me(v_txn uuid)\nreturns boolean\nlanguage sql security definer set search_path = public\nas $$\n  select exists (\n    select 1 from public.transactions t\n    where t.id = v_txn\n      and (\n        t.user_id = auth.uid()\n        or exists (\n          select 1 from public.counterparties c\n          where c.id = t.counterparty_id and c.linked_user_id = auth.uid()\n        )\n      )\n  );\n$$;\n\n-- آیا کاربر جاری می‌تواند کامنت‌های این تراکنش را ببیند/بگذارد؟\ncreate or replace function public.comment_visible_to_me(v_txn uuid)\nreturns boolean\nlanguage sql security definer set search_path = public\nas $$\n  select public.txn_visible_to_me(v_txn);\n$$;\n\n-- ============================================================\n-- ۳) تبدیل داده قدیمی: direction → kind (اجرای مجدد امن است)\n-- ============================================================\ndo $$\nbegin\n  if exists (select 1 from information_schema.columns\n             where table_schema = 'public' and table_name = 'transactions'\n               and column_name = 'direction') then\n    update public.transactions set kind = direction where kind is null;\n  end if;\nend\n$$;\n\n-- اگر تراکنش قدیمی بدون kind مانده (نباید)، مقدار پیش‌فرض\nupdate public.transactions set kind = 'paid_to' where kind is null;\n\nalter table public.transactions alter column kind set not null;\n\nalter table public.transactions drop constraint if exists txn_kind_check;\nalter table public.transactions\n  add constraint txn_kind_check\n  check (kind in ('opening_claim','opening_debt','claim','debt','paid_to','received_from'));\n\n-- ستون‌های تطابق (نسخه ۲) حذف می‌شوند — دیگر مورد استفاده نیستند\nalter table public.transactions drop constraint if exists fk_matched;\nalter table public.transactions drop column if exists matched_transaction_id;\nalter table public.transactions drop column if exists match_status;\nalter table public.transactions drop column if exists direction;\n\n-- ============================================================\n-- ۴) RLS: دسته‌بندی‌های شخصی\n-- ============================================================\nalter table public.categories enable row level security;\n\ndrop policy if exists \"cat_own_all\" on public.categories;\ncreate policy \"cat_own_all\" on public.categories\n  for all to authenticated\n  using (user_id = auth.uid())\n  with check (user_id = auth.uid());\n\n-- ============================================================\n-- ۵) RLS: گرنت‌های دسترسی (خواندن فقط؛ نوشتن از طریق Edge Function ادمین)\n-- ============================================================\nalter table public.counterparty_access enable row level security;\n\n-- کاربر گرنت‌های خودش را می‌بیند؛ ادمین همه را\ndrop policy if exists \"cp_access_select\" on public.counterparty_access;\ncreate policy \"cp_access_select\" on public.counterparty_access\n  for select to authenticated\n  using (user_id = auth.uid() or public.is_admin());\n\n-- ============================================================\n-- ۶) RLS: طرف‌حساب‌ها\n-- ============================================================\n\n-- سیاست دیدن طرف‌حساب‌ها جایگزین می‌شود (نسخه ۲ همه را می‌دیدند)\ndrop policy if exists \"cp_select\" on public.counterparties;\ncreate policy \"cp_select\" on public.counterparties\n  for select to authenticated\n  using (public.cp_visible_to_me(id));\n\n-- کاربر می‌تواند طرف‌حساب «شخصی» خودش را بسازد/ویرایش/حذف کند\ndrop policy if exists \"cp_own_private_write\" on public.counterparties;\ncreate policy \"cp_own_private_write\" on public.counterparties\n  for all to authenticated\n  using (is_shared = false and owner_user_id = auth.uid())\n  with check (is_shared = false and owner_user_id = auth.uid());\n\n-- ============================================================\n-- ۷) RLS: تراکنش‌ها\n-- ============================================================\n\n-- سیاست دیدن: دفتر خودم + تراکنش‌هایی که دیگران درباره من ثبت کرده‌اند\ndrop policy if exists \"tx_select_own\" on public.transactions;\ncreate policy \"tx_select_own\" on public.transactions\n  for select to authenticated\n  using (public.txn_visible_to_me(id));\n\n-- ============================================================\n-- ۸) RLS: کامنت‌ها\n-- ============================================================\nalter table public.transaction_comments enable row level security;\n\ndrop policy if exists \"tc_select\" on public.transaction_comments;\ncreate policy \"tc_select\" on public.transaction_comments\n  for select to authenticated\n  using (author_id = auth.uid() or public.comment_visible_to_me(transaction_id));\n\ndrop policy if exists \"tc_insert\" on public.transaction_comments;\ncreate policy \"tc_insert\" on public.transaction_comments\n  for insert to authenticated\n  with check (author_id = auth.uid() and public.comment_visible_to_me(transaction_id));\n\n-- ============================================================\n-- ۹) ایندکس‌ها\n-- ============================================================\ncreate index if not exists idx_tc_txn on public.transaction_comments(transaction_id);\ncreate index if not exists idx_cat_user on public.categories(user_id);\ncreate index if not exists idx_cpa_user_cp on public.counterparty_access(user_id, counterparty_id);\n\n-- ============================================================\n-- ۱۰) گزارش‌های ممیزی نمونه (اگر جدول موجود است — از v2)\n-- ============================================================\n-- (audit_logs دست‌نخورده می‌ماند؛ EF ها رکورد جدید می‌نویسند)\n";

export const CREATE_TRANSACTION_FN_V3 = "// supabase/functions/create-transaction/index.ts\n// ثبت تراکنش در دفتر مستقل کاربر — نسخه ۳.۰ (تطابق حذف شد)\n// شش kind: opening_claim / opening_debt / claim / debt / paid_to / received_from\n// Deploy: supabase functions deploy create-transaction\n\nimport { createClient } from \"https://esm.sh/@supabase/supabase-js@2\";\n\nconst KINDS = [\n  \"opening_claim\",\n  \"opening_debt\",\n  \"claim\",\n  \"debt\",\n  \"paid_to\",\n  \"received_from\",\n];\n\nconst cors = {\n  \"Access-Control-Allow-Origin\": \"*\",\n  \"Access-Control-Allow-Headers\": \"authorization, x-client-info, apikey, content-type\",\n};\n\nfunction json(data, status = 200) {\n  return new Response(JSON.stringify(data), {\n    status,\n    headers: { ...cors, \"Content-Type\": \"application/json\" },\n  });\n}\n\nDeno.serve(async (req) => {\n  if (req.method === \"OPTIONS\") return new Response(\"ok\", { headers: cors });\n  try {\n    const authHeader = req.headers.get(\"Authorization\") ?? \"\";\n    const userClient = createClient(\n      Deno.env.get(\"SUPABASE_URL\"),\n      Deno.env.get(\"SUPABASE_ANON_KEY\"),\n      { global: { headers: { Authorization: authHeader } } }\n    );\n    const { data: { user } } = await userClient.auth.getUser();\n    if (!user) return json({ error: \"احراز هویت نشده\" }, 401);\n\n    const body = await req.json();\n    const kind = body.kind;\n    const counterpartyId = body.counterpartyId;\n    const amount = Math.floor(Number(body.amount));\n    const currency = body.currency || \"IRT\";\n    const effectiveAt = body.effectiveAt; // شمسی yyyy-mm-dd\n    const description = body.description || null;\n    const categoryId = body.categoryId || null;\n    const idempotencyKey = body.idempotencyKey || crypto.randomUUID();\n\n    // اعتبارسنجی\n    if (!counterpartyId) return json({ error: \"طرف حساب الزامی است\" }, 400);\n    if (!KINDS.includes(kind)) return json({ error: \"نوع عملیات نامعتبر است\" }, 400);\n    if (!Number.isFinite(amount) || amount <= 0)\n      return json({ error: \"مبلغ نامعتبر\" }, 400);\n    if (!effectiveAt) return json({ error: \"تاریخ الزامی است\" }, 400);\n\n    const admin = createClient(\n      Deno.env.get(\"SUPABASE_URL\"),\n      Deno.env.get(\"SUPABASE_SERVICE_ROLE_KEY\")\n    );\n\n    // کاربر غیرفعال نمی‌تواند ثبت کند\n    const { data: myProfile } = await admin\n      .from(\"user_profiles\").select(\"is_active, display_name\").eq(\"id\", user.id).maybeSingle();\n    if (!myProfile) return json({ error: \"پروفایل کاربر یافت نشد\" }, 403);\n    if (myProfile.is_active === false)\n      return json({ error: \"حساب شما توسط ادمین غیرفعال شده است\" }, 403);\n\n    // طرف حساب\n    const { data: cp } = await admin\n      .from(\"counterparties\").select(\"*\").eq(\"id\", counterpartyId).maybeSingle();\n    if (!cp) return json({ error: \"طرف حساب یافت نشد\" }, 404);\n    if (cp.linked_user_id === user.id)\n      return json({ error: \"نمی‌توان با طرف حساب خودتان تراکنش ثبت کنید\" }, 400);\n\n    // دسترسی به طرف حساب:\n    //   شخصی → فقط مالکش | مشترک → ادمین یا داشتن گرنت\n    if (cp.is_shared === false) {\n      if (cp.owner_user_id !== user.id)\n        return json({ error: \"این طرف حساب شخصی شما نیست\" }, 403);\n    } else {\n      const isAdmin = myProfile.is_active && (await admin\n        .from(\"user_profiles\").select(\"role\").eq(\"id\", user.id).maybeSingle()\n      ).data?.role === \"admin\";\n      if (!isAdmin) {\n        const { count } = await admin\n          .from(\"counterparty_access\")\n          .select(\"*\", { count: \"exact\", head: true })\n          .eq(\"user_id\", user.id)\n          .eq(\"counterparty_id\", counterpartyId);\n        if (!count)\n          return json(\n            { error: \"ادمین به شما دسترسی این طرف حساب مشترک را نداده است\" },\n            403\n          );\n      }\n    }\n\n    // دسته‌بندی باید متعلق به خود کاربر باشد\n    if (categoryId) {\n      const { data: cat } = await admin\n        .from(\"categories\").select(\"id\").eq(\"id\", categoryId)\n        .eq(\"user_id\", user.id).maybeSingle();\n      if (!cat) return json({ error: \"دسته‌بندی نامعتبر است\" }, 400);\n    }\n\n    // idempotency: اگر تراکنش با همین کلید قبلاً ثبت شده، همان را برگردان\n    const { data: existing } = await admin\n      .from(\"transactions\").select(\"*\")\n      .eq(\"user_id\", user.id).eq(\"idempotency_key\", idempotencyKey).maybeSingle();\n    if (existing) return json({ ok: true, transaction: existing, idempotent: true });\n\n    // درج تراکنش — دفتر مستقل، بدون تطابق\n    const { data: txn, error } = await admin.from(\"transactions\").insert({\n      user_id: user.id,\n      counterparty_id: counterpartyId,\n      kind,\n      amount,\n      currency,\n      effective_at: effectiveAt,\n      created_by: user.id,\n      description,\n      category_id: categoryId,\n      status: \"POSTED\",\n      idempotency_key: idempotencyKey,\n    }).select().single();\n    if (error) return json({ error: error.message }, 500);\n\n    // گزارش ممیزی\n    await admin.from(\"audit_logs\").insert({\n      actor_id: user.id,\n      actor_name: myProfile.display_name || \"—\",\n      action: \"CREATE_TXN\",\n      entity_type: \"Transaction\",\n      entity_id: txn.id,\n      result: \"success\",\n      details: \"ثبت \" + amount + \" \" + kind + (categoryId ? \" — دسته‌بندی‌دار\" : \"\"),\n    });\n\n    return json({ ok: true, transaction: txn });\n  } catch (e) {\n    return json({ error: String(e) }, 500);\n  }\n});\n";

export const ADMIN_USERS_FN_V3 = "// supabase/functions/admin-users/index.ts\n// مدیریت کاربران توسط ادمین: GET (لیست) / POST (ایجاد) / PUT (ویرایش + فعال/غیرفعال) / DELETE (حذف)\n// نسخه ۳.۰ — ستون is_active اضافه شد\n// Deploy: supabase functions deploy admin-users\n\nimport { createClient } from \"https://esm.sh/@supabase/supabase-js@2\";\n\nconst cors = {\n  \"Access-Control-Allow-Origin\": \"*\",\n  \"Access-Control-Allow-Headers\": \"authorization, x-client-info, apikey, content-type\",\n};\n\nfunction json(data, status = 200) {\n  return new Response(JSON.stringify(data), {\n    status,\n    headers: { ...cors, \"Content-Type\": \"application/json\" },\n  });\n}\n\nasync function actorName(admin, id) {\n  const { data } = await admin.from(\"user_profiles\").select(\"display_name\").eq(\"id\", id).maybeSingle();\n  return data?.display_name || \"—\";\n}\n\nasync function requireAdmin(req) {\n  const authHeader = req.headers.get(\"Authorization\") ?? \"\";\n  const userClient = createClient(\n    Deno.env.get(\"SUPABASE_URL\"),\n    Deno.env.get(\"SUPABASE_ANON_KEY\"),\n    { global: { headers: { Authorization: authHeader } } }\n  );\n  const { data: { user } } = await userClient.auth.getUser();\n  if (!user) return { error: json({ error: \"احراز هویت نشده\" }, 401) };\n  const admin = createClient(\n    Deno.env.get(\"SUPABASE_URL\"),\n    Deno.env.get(\"SUPABASE_SERVICE_ROLE_KEY\")\n  );\n  const { data: prof } = await admin\n    .from(\"user_profiles\").select(\"role, is_active\").eq(\"id\", user.id).maybeSingle();\n  if (!prof || prof.role !== \"admin\")\n    return { error: json({ error: \"فقط ادمین دسترسی دارد\" }, 403) };\n  if (prof.is_active === false)\n    return { error: json({ error: \"حساب ادمین شما غیرفعال شده است\" }, 403) };\n  return { user, admin };\n}\n\nDeno.serve(async (req) => {\n  if (req.method === \"OPTIONS\") return new Response(\"ok\", { headers: cors });\n  const auth = await requireAdmin(req);\n  if (auth.error) return auth.error;\n  const { user: actor, admin } = auth;\n\n  // GET → لیست کاربران\n  if (req.method === \"GET\") {\n    const { data, error } = await admin.from(\"user_profiles\").select(\"*\").order(\"created_at\");\n    if (error) return json({ error: error.message }, 500);\n    return json({ users: data });\n  }\n\n  // POST → ایجاد کاربر\n  if (req.method === \"POST\") {\n    const b = await req.json();\n    const username = (b.username || \"\").trim().toLowerCase();\n    const password = b.password;\n    const displayName = (b.displayName || \"\").trim();\n    const role = b.role || \"user\";\n    const scope = b.scope || null;\n    const makeCounterparty = b.makeCounterparty !== false;\n\n    if (!username || username.length < 3)\n      return json({ error: \"نام کاربری حداقل ۳ نویسه\" }, 400);\n    if (!password || password.length < 4)\n      return json({ error: \"رمز حداقل ۴ نویسه\" }, 400);\n    if (!displayName) return json({ error: \"نام نمایشی الزامی\" }, 400);\n    if (role === \"user\" && !scope)\n      return json({ error: \"سطح دسترسی برای کاربر عادی الزامی\" }, 400);\n\n    // یکتایی username\n    const { data: dup } = await admin\n      .from(\"user_profiles\").select(\"id\").eq(\"username\", username).maybeSingle();\n    if (dup) return json({ error: \"نام کاربری قبلاً گرفته شده\" }, 400);\n\n    // ساخت کاربر در auth.users با email ساختگی\n    const email = username + \"@accounting.local\";\n    const { data: newUser, error: authErr } = await admin.auth.admin.createUser({\n      email,\n      password,\n      email_confirm: true,\n    });\n    if (authErr) return json({ error: authErr.message }, 500);\n\n    // درج پروفایل (is_active پیش‌فرض true)\n    const { error: profErr } = await admin.from(\"user_profiles\").insert({\n      id: newUser.user.id,\n      username,\n      display_name: displayName,\n      role,\n      scope: role === \"user\" ? scope : null,\n    });\n    if (profErr) return json({ error: profErr.message }, 500);\n\n    // ایجاد طرف حساب هم‌نام (مشترک) و لینک (اگر خواسته شده)\n    if (makeCounterparty) {\n      const { data: cp } = await admin.from(\"counterparties\").insert({\n        display_name: displayName,\n        linked_user_id: newUser.user.id,\n        linked_username: username,\n        is_shared: true,\n        created_by: actor.id,\n      }).select().single();\n      if (cp) {\n        await admin.from(\"user_profiles\").update({ linked_counterparty_id: cp.id })\n          .eq(\"id\", newUser.user.id);\n      }\n    }\n\n    await admin.from(\"audit_logs\").insert({\n      actor_id: actor.id,\n      actor_name: await actorName(admin, actor.id),\n      action: \"ADD_USER\",\n      entity_type: \"User\",\n      entity_id: newUser.user.id,\n      result: \"success\",\n      details: \"افزودن کاربر \" + displayName + \" (\" + username + \")\",\n    });\n    return json({ ok: true, userId: newUser.user.id });\n  }\n\n  // PUT → ویرایش (نام/سطح/رمز + فعال/غیرفعال)\n  if (req.method === \"PUT\") {\n    const url = new URL(req.url);\n    const id = url.searchParams.get(\"id\");\n    if (!id) return json({ error: \"id الزامی\" }, 400);\n    const b = await req.json();\n    const patch = {};\n    if (b.displayName) patch.display_name = b.displayName.trim();\n    if (b.scope) patch.scope = b.scope;\n    if (b.isActive !== undefined) patch.is_active = !!b.isActive;\n    if (Object.keys(patch).length) {\n      const { error } = await admin.from(\"user_profiles\").update(patch).eq(\"id\", id);\n      if (error) return json({ error: error.message }, 500);\n    }\n    if (b.password) {\n      const { error: pwErr } = await admin.auth.admin.updateUserById(id, { password: b.password });\n      if (pwErr) return json({ error: pwErr.message }, 500);\n    }\n    await admin.from(\"audit_logs\").insert({\n      actor_id: actor.id,\n      actor_name: await actorName(admin, actor.id),\n      action: \"UPDATE_USER\",\n      entity_type: \"User\",\n      entity_id: id,\n      result: \"success\",\n      details:\n        \"ویرایش کاربر\" +\n        (b.isActive !== undefined ? (b.isActive ? \" — فعال شد\" : \" — غیرفعال شد\") : \"\"),\n    });\n    return json({ ok: true });\n  }\n\n  // DELETE → حذف\n  if (req.method === \"DELETE\") {\n    const url = new URL(req.url);\n    const id = url.searchParams.get(\"id\");\n    if (!id) return json({ error: \"id الزامی\" }, 400);\n    if (id === actor.id) return json({ error: \"نمی‌توانید خودتان را حذف کنید\" }, 400);\n    const { error } = await admin.auth.admin.deleteUser(id);\n    if (error) return json({ error: error.message }, 500);\n    await admin.from(\"audit_logs\").insert({\n      actor_id: actor.id,\n      actor_name: await actorName(admin, actor.id),\n      action: \"DELETE_USER\",\n      entity_type: \"User\",\n      entity_id: id,\n      result: \"success\",\n      details: \"حذف کاربر\",\n    });\n    return json({ ok: true });\n  }\n\n  return json({ error: \"متد پشتیبانی نمی‌شود\" }, 405);\n});\n";

export const ADMIN_COUNTERPARTIES_FN_V3 = "// supabase/functions/admin-counterparties/index.ts\n// مدیریت طرف‌حساب‌های «مشترک» توسط ادمین — نسخه ۳.۰\n// GET (لیست) / POST (ایجاد طرف‌حساب مشترک یا grant/revoke دسترسی)\n// PUT (ویرایش + لینک کاربر = دادن پنل) / DELETE (حذف)\n// Deploy: supabase functions deploy admin-counterparties\n\nimport { createClient } from \"https://esm.sh/@supabase/supabase-js@2\";\n\nconst cors = {\n  \"Access-Control-Allow-Origin\": \"*\",\n  \"Access-Control-Allow-Headers\": \"authorization, x-client-info, apikey, content-type\",\n};\n\nfunction json(data, status = 200) {\n  return new Response(JSON.stringify(data), {\n    status,\n    headers: { ...cors, \"Content-Type\": \"application/json\" },\n  });\n}\n\nasync function actorName(admin, id) {\n  const { data } = await admin.from(\"user_profiles\").select(\"display_name\").eq(\"id\", id).maybeSingle();\n  return data?.display_name || \"—\";\n}\n\nasync function requireAdmin(req) {\n  const authHeader = req.headers.get(\"Authorization\") ?? \"\";\n  const userClient = createClient(\n    Deno.env.get(\"SUPABASE_URL\"),\n    Deno.env.get(\"SUPABASE_ANON_KEY\"),\n    { global: { headers: { Authorization: authHeader } } }\n  );\n  const { data: { user } } = await userClient.auth.getUser();\n  if (!user) return { error: json({ error: \"احراز هویت نشده\" }, 401) };\n  const admin = createClient(\n    Deno.env.get(\"SUPABASE_URL\"),\n    Deno.env.get(\"SUPABASE_SERVICE_ROLE_KEY\")\n  );\n  const { data: prof } = await admin\n    .from(\"user_profiles\").select(\"role, is_active\").eq(\"id\", user.id).maybeSingle();\n  if (!prof || prof.role !== \"admin\")\n    return { error: json({ error: \"فقط ادمین دسترسی دارد\" }, 403) };\n  if (prof.is_active === false)\n    return { error: json({ error: \"حساب ادمین شما غیرفعال شده است\" }, 403) };\n  return { user, admin };\n}\n\nDeno.serve(async (req) => {\n  if (req.method === \"OPTIONS\") return new Response(\"ok\", { headers: cors });\n  const auth = await requireAdmin(req);\n  if (auth.error) return auth.error;\n  const { user: actor, admin } = auth;\n\n  if (req.method === \"GET\") {\n    const { data, error } = await admin.from(\"counterparties\").select(\"*\").order(\"created_at\");\n    if (error) return json({ error: error.message }, 500);\n    return json({ counterparties: data });\n  }\n\n  if (req.method === \"POST\") {\n    const b = await req.json();\n\n    // ---- action: grant / revoke (نسخه ۳) ----\n    if (b.action === \"grant\" || b.action === \"revoke\") {\n      const userId = b.userId;\n      const counterpartyId = b.counterpartyId;\n      if (!userId || !counterpartyId)\n        return json({ error: \"userId و counterpartyId الزامی\" }, 400);\n      const { data: cp } = await admin\n        .from(\"counterparties\").select(\"id, display_name, is_shared, linked_user_id\")\n        .eq(\"id\", counterpartyId).maybeSingle();\n      if (!cp) return json({ error: \"طرف حساب یافت نشد\" }, 404);\n      if (cp.is_shared === false)\n        return json({ error: \"طرف حساب شخصی است؛ گرنت معنا ندارد\" }, 400);\n      if (cp.linked_user_id === userId)\n        return json({ error: \"این کاربر نماینده خودِ این طرف حساب است\" }, 400);\n      const { data: target } = await admin\n        .from(\"user_profiles\").select(\"display_name\").eq(\"id\", userId).maybeSingle();\n      if (!target) return json({ error: \"کاربر یافت نشد\" }, 404);\n\n      if (b.action === \"grant\") {\n        const { error } = await admin.from(\"counterparty_access\").insert({\n          user_id: userId,\n          counterparty_id: counterpartyId,\n          granted_by: actor.id,\n        });\n        if (error) {\n          if (String(error.code) === \"23505\")\n            return json({ ok: true, note: \"این دسترسی از قبل وجود دارد\" });\n          return json({ error: error.message }, 500);\n        }\n        await admin.from(\"audit_logs\").insert({\n          actor_id: actor.id,\n          actor_name: await actorName(admin, actor.id),\n          action: \"GRANT_CP_ACCESS\",\n          entity_type: \"CounterpartyAccess\",\n          entity_id: counterpartyId,\n          result: \"success\",\n          details: \"دادن دسترسی طرف‌حساب «\" + cp.display_name + \"» به «\" + target.display_name + \"»\",\n        });\n        return json({ ok: true });\n      }\n\n      // revoke\n      await admin.from(\"counterparty_access\")\n        .delete()\n        .eq(\"user_id\", userId)\n        .eq(\"counterparty_id\", counterpartyId);\n      await admin.from(\"audit_logs\").insert({\n        actor_id: actor.id,\n        actor_name: await actorName(admin, actor.id),\n        action: \"REVOKE_CP_ACCESS\",\n        entity_type: \"CounterpartyAccess\",\n        entity_id: counterpartyId,\n        result: \"success\",\n        details: \"گرفتن دسترسی طرف‌حساب «\" + cp.display_name + \"» از «\" + target.display_name + \"»\",\n      });\n      return json({ ok: true });\n    }\n\n    // ---- ایجاد طرف‌حساب مشترک ----\n    const displayName = (b.displayName || \"\").trim();\n    if (!displayName) return json({ error: \"نام الزامی\" }, 400);\n    let linkedUsername = null;\n    if (b.linkedUserId) {\n      const { data: lu } = await admin\n        .from(\"user_profiles\").select(\"username\").eq(\"id\", b.linkedUserId).maybeSingle();\n      if (!lu) return json({ error: \"کاربر لینک‌شده یافت نشد\" }, 400);\n      const { data: dup } = await admin\n        .from(\"counterparties\").select(\"id\").eq(\"linked_user_id\", b.linkedUserId).maybeSingle();\n      if (dup) return json({ error: \"کاربر قبلاً به طرف حساب دیگری لینک شده\" }, 400);\n      linkedUsername = lu.username;\n    }\n    const { data: cp, error } = await admin.from(\"counterparties\").insert({\n      display_name: displayName,\n      notes: b.notes || null,\n      linked_user_id: b.linkedUserId || null,\n      linked_username: linkedUsername,\n      is_shared: true, // طرف‌حساب‌های ادمین همیشه مشترک‌اند\n      owner_user_id: null,\n      created_by: actor.id,\n    }).select().single();\n    if (error) return json({ error: error.message }, 500);\n    // sync: اگر لینک شد، linked_counterparty_id کاربر را هم set کن\n    if (b.linkedUserId) {\n      await admin.from(\"user_profiles\").update({ linked_counterparty_id: cp.id })\n        .eq(\"id\", b.linkedUserId);\n    }\n    return json({ ok: true, counterparty: cp });\n  }\n\n  if (req.method === \"PUT\") {\n    const url = new URL(req.url);\n    const id = url.searchParams.get(\"id\");\n    if (!id) return json({ error: \"id الزامی\" }, 400);\n    const b = await req.json();\n\n    // فقط طرف‌حساب مشترک قابل ویرایش توسط ادمین است\n    const { data: cp } = await admin\n      .from(\"counterparties\").select(\"is_shared, owner_user_id\").eq(\"id\", id).maybeSingle();\n    if (!cp) return json({ error: \"طرف حساب یافت نشد\" }, 404);\n    if (cp.is_shared === false)\n      return json({ error: \"طرف حساب شخصی فقط به مالکش تعلق دارد\" }, 403);\n\n    const patch = {};\n    if (b.displayName) patch.display_name = b.displayName.trim();\n    if (b.notes !== undefined) patch.notes = b.notes || null;\n    if (b.linkedUserId !== undefined) {\n      if (b.linkedUserId) {\n        const { data: lu } = await admin\n          .from(\"user_profiles\").select(\"username\").eq(\"id\", b.linkedUserId).maybeSingle();\n        if (!lu) return json({ error: \"کاربر یافت نشد\" }, 400);\n        const { data: dup } = await admin\n          .from(\"counterparties\").select(\"id\").neq(\"id\", id).eq(\"linked_user_id\", b.linkedUserId).maybeSingle();\n        if (dup) return json({ error: \"کاربر قبلاً لینک شده\" }, 400);\n        patch.linked_user_id = b.linkedUserId;\n        patch.linked_username = lu.username;\n      } else {\n        patch.linked_user_id = null;\n        patch.linked_username = null;\n      }\n    }\n    const { error } = await admin.from(\"counterparties\").update(patch).eq(\"id\", id);\n    if (error) return json({ error: error.message }, 500);\n    // sync user_profiles\n    const { data: cpAfter } = await admin.from(\"counterparties\").select(\"linked_user_id\").eq(\"id\", id).maybeSingle();\n    if (cpAfter?.linked_user_id) {\n      await admin.from(\"user_profiles\").update({ linked_counterparty_id: id }).eq(\"id\", cpAfter.linked_user_id);\n    }\n    return json({ ok: true });\n  }\n\n  if (req.method === \"DELETE\") {\n    const url = new URL(req.url);\n    const id = url.searchParams.get(\"id\");\n    if (!id) return json({ error: \"id الزامی\" }, 400);\n    const { data: cp } = await admin\n      .from(\"counterparties\").select(\"is_shared\").eq(\"id\", id).maybeSingle();\n    if (!cp) return json({ ok: true });\n    if (cp.is_shared === false)\n      return json({ error: \"حذف طرف حساب شخصی به مالکش واگذار شده است\" }, 403);\n    const { count } = await admin.from(\"transactions\").select(\"*\", { count: \"exact\", head: true }).eq(\"counterparty_id\", id);\n    if (count && count > 0) return json({ error: \"طرف حساب تراکنش دارد و قابل حذف نیست\" }, 400);\n    await admin.from(\"counterparty_access\").delete().eq(\"counterparty_id\", id);\n    await admin.from(\"counterparties\").delete().eq(\"id\", id);\n    return json({ ok: true });\n  }\n\n  return json({ error: \"متد پشتیبانی نمی‌شود\" }, 405);\n});\n";

export const TELEGRAM_BOT_FN_V3 = "// Edge Function: telegram-bot (v3.0.1 — دفترهای مستقل + شش نوع عملیات)\n// مسیر: supabase/functions/telegram-bot/index.ts\n// دیپلوی: supabase functions deploy telegram-bot --no-verify-jwt\n//\n// تغییرات نسخه ۳:\n//   - مانده بر پایه kind (به‌جای direction)\n//   - کاربر غیرفعال (is_active=false) پاسخ نمی‌گیرد و نمی‌تواند کد اتصال مصرف کند\n//   - در فهرست تراکنش‌ها دسته‌بندی هم نمایش داده می‌شود\n//\n// تغییرات ۳.۰.۱:\n//   - رفع باگ نمایش برعکسِ تاریخ شمسی در متن RTL تلگرام:\n//     تاریخ با ارقام فارسی «۱۴۰۵/۰۸/۰۴» + قفل جهت LTR (U+200E) نمایش داده می‌شود\n\nimport { createClient } from \"https://esm.sh/@supabase/supabase-js@2\";\n\nconst SUPABASE_URL = Deno.env.get(\"SUPABASE_URL\") ?? \"\";\nconst SERVICE_ROLE_KEY = Deno.env.get(\"SUPABASE_SERVICE_ROLE_KEY\") ?? \"\";\nconst BOT_TOKEN = Deno.env.get(\"TELEGRAM_BOT_TOKEN\") ?? \"\";\nconst WEBHOOK_SECRET = Deno.env.get(\"TELEGRAM_WEBHOOK_SECRET\") ?? \"\";\nconst TELEGRAM_API = \"https://api.telegram.org/bot\" + BOT_TOKEN;\n\nconst corsHeaders = {\n  \"Access-Control-Allow-Origin\": \"*\",\n  \"Access-Control-Allow-Headers\": \"authorization, x-client-info, apikey, content-type\",\n};\n\nfunction json(data: unknown, status = 200) {\n  return new Response(JSON.stringify(data), {\n    status,\n    headers: { ...corsHeaders, \"Content-Type\": \"application/json\" },\n  });\n}\n\n// تبدیل ارقام فارسی/عربی به لاتین\nfunction toLatin(s: string): string {\n  const fa = \"۰۱۲۳۴۵۶۷۸۹\";\n  const ar = \"٠١٢٣٤٥٦٧٨٩\";\n  return s\n    .replace(/[\\u06F0-\\u06F9]/g, (d: string) => String(fa.indexOf(d)))\n    .replace(/[\\u0660-\\u0669]/g, (d: string) => String(ar.indexOf(d)));\n}\n\nasync function tg(chatId: number, text: string, replyMarkup?: unknown) {\n  const body: Record<string, unknown> = { chat_id: chatId, text, parse_mode: \"HTML\" };\n  if (replyMarkup) body.reply_markup = replyMarkup;\n  try {\n    await fetch(TELEGRAM_API + \"/sendMessage\", {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\" },\n      body: JSON.stringify(body),\n    });\n  } catch (e) {\n    console.error(\"tg error:\", e);\n  }\n}\n\nfunction mainMenu() {\n  return {\n    keyboard: [\n      [{ text: \"📊 مانده من\" }, { text: \"📋 تراکنش‌ها\" }],\n      [{ text: \"🔗 اتصال با کد\" }, { text: \"❓ راهنما\" }],\n    ],\n    resize_keyboard: true,\n    one_time_keyboard: false,\n    is_persistent: true,\n  };\n}\n\nfunction txnCountKeyboard() {\n  return {\n    inline_keyboard: [\n      [\n        { text: \"۱۰ اخیر\", callback_data: \"txns_10\" },\n        { text: \"۳۰ اخیر\", callback_data: \"txns_30\" },\n        { text: \"همه\", callback_data: \"txns_all\" },\n      ],\n    ],\n  };\n}\n\nfunction scopeLabel(scope: string | null | undefined): string {\n  if (scope === \"balance_only\") return \"فقط مانده\";\n  return \"فهرست تراکنش‌ها\";\n}\n\nfunction fmt(n: number): string {\n  return n.toLocaleString(\"en-US\");\n}\n\n// ارقام لاتین → ارقام فارسی\nfunction toFa(s: string): string {\n  const D = \"۰۱۲۳۴۵۶۷۸۹\";\n  return s.replace(/\\d/g, (d) => D[+d]);\n}\n\n// تاریخ شمسی ذخیره‌شده (\"1405-08-04\") → «۱۴۰۵/۰۸/۰۴»\n// چرا؟ در متن RTL، تاریخِ لاتین با خط تیره توسط الگوریتم bidi تکه‌تکه و\n// برعکس (04-08-1405) رندر می‌شود. با ارقام فارسی + اسلش + دو کاراکتر\n// نامرئی U+200E (LRM) در ابتدا و انتها، کل تاریخ یک تکهٔ LTR می‌شود و\n// همیشه درست نمایش داده می‌شود.\nfunction faDate(s: string): string {\n  if (!s) return \"\";\n  const m = /^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(String(s).trim());\n  if (!m) return String(s);\n  const d = toFa(m[1]) + \"/\" + toFa(m[2]) + \"/\" + toFa(m[3]);\n  return \"\\u200E\" + d + \"\\u200E\";\n}\n\n// برچسب شش نوع عملیات\nconst KIND_LABELS: Record<string, string> = {\n  opening_claim: \"ثبت طلب اولیه\",\n  opening_debt: \"ثبت بدهی اولیه\",\n  claim: \"ثبت طلب\",\n  debt: \"ثبت بدهی\",\n  paid_to: \"پرداخت به\",\n  received_from: \"دریافت از\",\n};\n\n// kinds «دریافت‌مانند» → مانده به بدهی شما می‌رود\nfunction isReceivedLike(kind: string): boolean {\n  return kind === \"received_from\" || kind === \"debt\" || kind === \"opening_debt\";\n}\n\ninterface V3Txn {\n  kind: string;\n  amount: number;\n  currency: string;\n  effective_at: string;\n  description: string | null;\n  counterparties: { display_name: string } | null;\n  categories: { name: string } | null;\n}\n\n// مانده به تفکیک طرف حساب — همان منطق engine v3\n// receivedLike (دریافت از، ثبت بدهی، ثبت بدهی اولیه) → net ↑ (بدهکارم)\n// paidLike    (پرداخت به، ثبت طلب، ثبت طلب اولیه) → net ↓ (طلبکارم)\nfunction computeBalances(txns: V3Txn[]) {\n  const byCp = new Map<string, { name: string; received: number; paid: number }>();\n  for (const t of txns) {\n    const key = t.counterparties?.display_name ?? \"نامشخص\";\n    const row = byCp.get(key) ?? { name: key, received: 0, paid: 0 };\n    if (isReceivedLike(t.kind)) row.received += t.amount;\n    else row.paid += t.amount;\n    byCp.set(key, row);\n  }\n  let totalReceivable = 0;\n  let totalPayable = 0;\n  const rows: Array<{ name: string; receivable: number; payable: number }> = [];\n  for (const r of byCp.values()) {\n    const net = r.received - r.paid;\n    const receivable = Math.max(-net, 0);\n    const payable = Math.max(net, 0);\n    totalReceivable += receivable;\n    totalPayable += payable;\n    rows.push({ name: r.name, receivable, payable });\n  }\n  rows.sort((a, b) => (b.receivable + b.payable) - (a.receivable + a.payable));\n  return { rows, totalReceivable, totalPayable };\n}\n\n// استاندارد پیام خطای غیرفعال/تلگرام‌قطع\nconst INACTIVE_MSG = \"⛔ حساب شما توسط ادمین سامانه غیرفعال شده است.\";\nconst TG_DISABLED_MSG = \"⛔ ادمین سامانه دسترسی تلگرام شما را غیرفعال کرده است.\";\n\nDeno.serve(async (req: Request) => {\n  if (req.method === \"OPTIONS\") return new Response(\"ok\", { headers: corsHeaders });\n  if (req.method !== \"POST\") return json({ error: \"Method not allowed\" }, 405);\n\n  // اعتبارسنجی وب‌هوک (اختیاری)\n  if (WEBHOOK_SECRET) {\n    const got = req.headers.get(\"X-Telegram-Bot-Api-Secret-Token\") ?? \"\";\n    if (got !== WEBHOOK_SECRET) return json({ error: \"Forbidden\" }, 403);\n  }\n\n  let update: any;\n  try { update = await req.json(); } catch { return json({ error: \"Invalid JSON\" }, 400); }\n\n  const supabase = createClient(SUPABASE_URL, SERVICE_ROLE_KEY);\n\n  // ===== Callback Query (دکمه‌های شیشه‌ای) =====\n  if (update.callback_query) {\n    const cbId = update.callback_query.id;\n    const cbChatId = update.callback_query.message?.chat?.id;\n    const cbData = update.callback_query.data;\n    const cbUserId = update.callback_query.from?.id;\n\n    try {\n      await fetch(TELEGRAM_API + \"/answerCallbackQuery\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ callback_query_id: cbId }),\n      });\n    } catch {}\n\n    if (cbData?.startsWith(\"txns_\")) {\n      const { data: link } = await supabase\n        .from(\"telegram_links\")\n        .select(\"user_id\")\n        .eq(\"telegram_user_id\", cbUserId)\n        .eq(\"status\", \"linked\")\n        .maybeSingle();\n      if (!link) {\n        if (cbChatId) await tg(cbChatId, \"❌ حساب شما متصل نیست.\", mainMenu());\n        return json({ ok: true });\n      }\n      const { data: profile } = await supabase\n        .from(\"user_profiles\")\n        .select(\"scope, telegram_enabled, is_active\")\n        .eq(\"id\", link.user_id)\n        .maybeSingle();\n      if (profile?.is_active === false) {\n        if (cbChatId) await tg(cbChatId, INACTIVE_MSG, mainMenu());\n        return json({ ok: true });\n      }\n      if (profile?.telegram_enabled === false) {\n        if (cbChatId) await tg(cbChatId, TG_DISABLED_MSG, mainMenu());\n        return json({ ok: true });\n      }\n      if (profile?.scope === \"balance_only\") {\n        if (cbChatId) await tg(cbChatId,\n          \"⚠️ سطح دسترسی شما «فقط مانده» است و اجازه مشاهده تراکنش‌ها را ندارید.\\n\" +\n          \"برای مشاهده مانده: دکمه «📊 مانده من» را بزنید.\",\n          mainMenu()\n        );\n        return json({ ok: true });\n      }\n      const limit = cbData === \"txns_all\" ? 500 : parseInt(cbData.split(\"_\")[1] ?? \"10\", 10);\n      const { data: txns } = await supabase\n        .from(\"transactions\")\n        .select(\"kind, amount, currency, effective_at, description, counterparties(display_name), categories(name)\")\n        .eq(\"user_id\", link.user_id)\n        .eq(\"status\", \"POSTED\")\n        .order(\"created_at\", { ascending: false })\n        .limit(limit);\n      const txList = (txns ?? []) as V3Txn[];\n      if (txList.length === 0) {\n        if (cbChatId) await tg(cbChatId, \"📭 تراکنشی برای نمایش وجود ندارد.\", mainMenu());\n        return json({ ok: true });\n      }\n      const currency = txList[0]?.currency || \"IRT\";\n      const label = currency === \"IRT\" ? \"تومان\" : \"ریال\";\n      let msg = \"📋 <b>تراکنش‌های شما</b> (\" + (cbData === \"txns_all\" ? \"همه\" : String(limit)) + \" مورد — جدید به قدیم)\\n\\n\";\n      for (const t of txList) {\n        const cp = t.counterparties?.display_name ?? \"نامشخص\";\n        const kindLabel = KIND_LABELS[t.kind] ?? t.kind;\n        // 🟢 = طلب‌ساز برای شما (پرداخت‌مانند) | 🔴 = بدهی‌ساز برای شما (دریافت‌مانند)\n        const dateStr = faDate(t.effective_at);\n        if (isReceivedLike(t.kind)) {\n          msg += \"🔴 \" + kindLabel + \" <b>\" + cp + \"</b>: \" + fmt(t.amount) + \" \" + label + \" | \" + dateStr;\n        } else {\n          msg += \"🟢 \" + kindLabel + \" <b>\" + cp + \"</b>: \" + fmt(t.amount) + \" \" + label + \" | \" + dateStr;\n        }\n        if (t.categories?.name) msg += \" | دسته: \" + t.categories.name;\n        if (t.description) msg += \" | \" + t.description;\n        msg += \"\\n\";\n      }\n      if (cbChatId) await tg(cbChatId, msg, mainMenu());\n    }\n    return json({ ok: true });\n  }\n\n  // ===== پیام‌های معمولی =====\n  const message = update.message;\n  if (!message || !message.chat || !message.from) return json({ ok: true });\n  const chatId = message.chat.id;\n  const text = (message.text ?? \"\").trim();\n  const telegramUserId = message.from.id;\n  const telegramUsername = message.from.username;\n\n  try {\n    // ===== /start =====\n    if (text === \"/start\") {\n      await tg(chatId,\n        \"👋 سلام!\\n\\n\" +\n        \"این ربات برای مشاهده مانده بدهی و طلب شماست.\\n\\n\" +\n        \"📝 <b>چه کار کنید:</b>\\n\" +\n        \"۱. از ادمین سامانه کد اتصال ۶ رقمی بگیرید.\\n\" +\n        \"۲. کد ۶ رقمی را همین‌جا بفرستید (یا <code>/link 123456</code>).\\n\" +\n        \"۳. بعد از اتصال، دکمه «📊 مانده من» را بزنید.\\n\\n\" +\n        \"دستورها: <code>/balance</code> ، <code>/transactions</code> ، <code>/help</code>\",\n        mainMenu()\n      );\n      return json({ ok: true });\n    }\n\n    // ===== اتصال با کد =====\n    const isLinkButton = text === \"🔗 اتصال با کد\";\n    const latinText = toLatin(text);\n    const isSixDigits = /^\\d{6}$/.test(latinText);\n    const isLinkCommand = text.startsWith(\"/link \");\n\n    if (isLinkButton) {\n      await tg(chatId,\n        \"🔗 برای اتصال:\\n\" +\n        \"۱. از ادمین سامانه کد اتصال ۶ رقمی بگیرید.\\n\" +\n        \"۲. کد ۶ رقمی را همین‌جا بفرستید.\\n\" +\n        \"مثال: <code>123456</code> یا <code>/link 123456</code>\",\n        mainMenu()\n      );\n      return json({ ok: true });\n    }\n\n    if (isLinkCommand || isSixDigits) {\n      const rawCode = isLinkCommand ? text.replace(\"/link\", \"\").trim() : text;\n      const code = toLatin(rawCode);\n      if (!/^\\d{6}$/.test(code)) {\n        await tg(chatId, \"❌ کد باید ۶ رقم باشد. مثال: <code>/link 123456</code>\", mainMenu());\n        return json({ ok: true });\n      }\n      const { data: linkCode } = await supabase\n        .from(\"telegram_link_codes\")\n        .select(\"id, user_id\")\n        .eq(\"code\", code)\n        .eq(\"used\", false)\n        .gt(\"expires_at\", new Date().toISOString())\n        .maybeSingle();\n      if (!linkCode) {\n        await tg(chatId, \"❌ کد نامعتبر، منقضی یا قبلاً استفاده شده است.\\nکد جدید را از ادمین سامانه بگیرید.\", mainMenu());\n        return json({ ok: true });\n      }\n      const { data: profile } = await supabase\n        .from(\"user_profiles\")\n        .select(\"display_name, scope, telegram_enabled, is_active\")\n        .eq(\"id\", linkCode.user_id)\n        .maybeSingle();\n      if (!profile) {\n        await tg(chatId, \"❌ پروفایل کاربر پیدا نشد. با ادمین تماس بگیرید.\", mainMenu());\n        return json({ ok: true });\n      }\n      if (profile.is_active === false) {\n        await tg(chatId, INACTIVE_MSG, mainMenu());\n        return json({ ok: true });\n      }\n      if (profile.telegram_enabled === false) {\n        await tg(chatId, TG_DISABLED_MSG, mainMenu());\n        return json({ ok: true });\n      }\n      // کد مصرف شد\n      await supabase\n        .from(\"telegram_link_codes\")\n        .update({ used: true, used_at: new Date().toISOString() })\n        .eq(\"id\", linkCode.id);\n      // اتصال — هر تلگرام فقط به یک کاربر؛ اتصال قبلی همان تلگرام جایگزین می‌شود\n      await supabase\n        .from(\"telegram_links\")\n        .upsert({\n          telegram_user_id: telegramUserId,\n          user_id: linkCode.user_id,\n          telegram_username: telegramUsername ? \"@\" + telegramUsername : null,\n          status: \"linked\",\n          linked_at: new Date().toISOString(),\n        }, { on_conflict: \"telegram_user_id\" });\n      await tg(chatId,\n        \"✅ اتصال موفق بود!\\n\\n\" +\n        \"نام کاربر: <b>\" + profile.display_name + \"</b>\\n\" +\n        \"سطح دسترسی: \" + scopeLabel(profile.scope) + \"\\n\\n\" +\n        \"حالا دکمه «📊 مانده من» را بزنید.\",\n        mainMenu()\n      );\n      return json({ ok: true });\n    }\n\n    // ===== مانده و تراکنش‌ها =====\n    const isBalance = text === \"/balance\" || text === \"📊 مانده من\";\n    const isTransactions = text === \"/transactions\" || text === \"📋 تراکنش‌ها\";\n\n    if (isBalance || isTransactions) {\n      const { data: link } = await supabase\n        .from(\"telegram_links\")\n        .select(\"user_id\")\n        .eq(\"telegram_user_id\", telegramUserId)\n        .eq(\"status\", \"linked\")\n        .maybeSingle();\n      if (!link) {\n        await tg(chatId,\n          \"❌ حساب شما متصل نیست.\\n\" +\n          \"دکمه «🔗 اتصال با کد» را بزنید.\",\n          mainMenu()\n        );\n        return json({ ok: true });\n      }\n      const { data: profile } = await supabase\n        .from(\"user_profiles\")\n        .select(\"scope, telegram_enabled, is_active\")\n        .eq(\"id\", link.user_id)\n        .maybeSingle();\n      const balanceOnly = profile?.scope === \"balance_only\";\n      if (profile?.is_active === false) {\n        await tg(chatId, INACTIVE_MSG, mainMenu());\n        return json({ ok: true });\n      }\n      if (profile?.telegram_enabled === false) {\n        await tg(chatId, TG_DISABLED_MSG, mainMenu());\n        return json({ ok: true });\n      }\n\n      const { data: txns } = await supabase\n        .from(\"transactions\")\n        .select(\"kind, amount, currency, effective_at, description, counterparties(display_name), categories(name)\")\n        .eq(\"user_id\", link.user_id)\n        .eq(\"status\", \"POSTED\")\n        .order(\"created_at\", { ascending: false });\n      const txList = (txns ?? []) as V3Txn[];\n      const { rows, totalReceivable, totalPayable } = computeBalances(txList);\n      const currency = (txList[0]?.currency) || \"IRT\";\n      const label = currency === \"IRT\" ? \"تومان\" : \"ریال\";\n\n      let msg = \"📊 <b>مانده شما</b>\\n\\n\";\n      msg += \"🟢 طلب شما (به شما بدهکارند): <b>\" + fmt(totalReceivable) + \"</b> \" + label + \"\\n\";\n      msg += \"🔴 بدهی شما (به آن‌ها بدهکارید): <b>\" + fmt(totalPayable) + \"</b> \" + label + \"\\n\";\n\n      if (isTransactions && balanceOnly) {\n        msg += \"\\n⚠️ سطح دسترسی شما «فقط مانده» است و اجازه مشاهده تراکنش‌ها را ندارید.\";\n        await tg(chatId, msg, mainMenu());\n        return json({ ok: true });\n      }\n\n      if (isBalance) {\n        if (!balanceOnly && rows.length > 0) {\n          msg += \"\\n<b>به تفکیک طرف حساب:</b>\\n\";\n          for (const r of rows.slice(0, 10)) {\n            if (r.receivable > 0) msg += \"• \" + r.name + \": طلب \" + fmt(r.receivable) + \"\\n\";\n            else if (r.payable > 0) msg += \"• \" + r.name + \": بدهی \" + fmt(r.payable) + \"\\n\";\n            else msg += \"• \" + r.name + \": تسویه ✅\\n\";\n          }\n        }\n        msg += \"\\nبرای مشاهده تراکنش‌ها، دکمه «📋 تراکنش‌ها» را بزنید.\";\n        await tg(chatId, msg, mainMenu());\n        return json({ ok: true });\n      }\n\n      // تراکنش‌ها — انتخاب تعداد\n      msg += \"\\nتعداد تراکنش مورد نظر را انتخاب کنید:\";\n      await tg(chatId, msg, txnCountKeyboard());\n      return json({ ok: true });\n    }\n\n    // ===== راهنما =====\n    if (text === \"/help\" || text === \"❓ راهنما\") {\n      await tg(chatId,\n        \"📖 <b>راهنما</b>\\n\\n\" +\n        \"📊 <b>مانده من</b> — کل طلب و بدهی شما\\n\" +\n        \"📋 <b>تراکنش‌ها</b> — فهرست تراکنش‌ها (طبق سطح دسترسی)\\n\" +\n        \"🔗 <b>اتصال با کد</b> — اتصال با کد ۶ رقمی که ادمین به شما می‌دهد\\n\" +\n        \"❓ <b>راهنما</b> — همین پیام\\n\\n\" +\n        \"🔴 در فهرست تراکنش‌ها: عملیات بدهی‌ساز برای شما\\n\" +\n        \"🟢 عملیات طلب‌ساز برای شما\\n\\n\" +\n        \"دستورها: <code>/start</code> ، <code>/link 123456</code> ، <code>/balance</code> ، <code>/transactions</code> ، <code>/help</code>\",\n        mainMenu()\n      );\n      return json({ ok: true });\n    }\n\n    // ===== پیام نامشخص =====\n    await tg(chatId,\n      \"❓ پیام شما را متوجه نشدم.\\n\" +\n      \"دکمه «❓ راهنما» را بزنید یا <code>/help</code> را تایپ کنید.\",\n      mainMenu()\n    );\n    return json({ ok: true });\n  } catch (e) {\n    console.error(\"Bot error:\", e);\n    await tg(chatId, \"⚠️ خطای سرور. بعداً تلاش کنید.\", mainMenu());\n    return json({ ok: true });\n  }\n});\n";

